content:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --row-hover: #f1f5f9;
  --stripe-bg: #f8fafc;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  padding: 24px 16px;
}

.app-container {
  max-width: 960px;
  margin: 0 auto;
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダーエリア */
.header {
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 20px;
}

.title {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* 操作バー・検索エリア */
.controls-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.search-box {
  position: relative;
  flex: 1;
  min-width: 240px;
  display: flex;
  align-items: center;
}

.search-icon {
  position: absolute;
  left: 12px;
  width: 18px;
  height: 18px;
  color: var(--text-light);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 10px 14px 10px 38px;
  font-size: 0.95rem;
  color: var(--text-main);
  background-color: #fff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.search-input::placeholder {
  color: var(--text-light);
}

.reset-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.reset-btn:hover {
  background-color: #e2e8f0;
  color: var(--text-main);
}

.reset-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(100, 116, 139, 0.2);
}

.stats-badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--primary-color);
  background-color: var(--primary-light);
  padding: 8px 14px;
  border-radius: 9999px;
  white-space: nowrap;
}

/* テーブルスタイル */
.table-container {
  overflow: hidden;
  overflow-x: auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: #fff;
  box-shadow: var(--shadow-sm);
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.table-head {
  background-color: #f8fafc;
  border-bottom: 2px solid var(--border-color);
}

.table-header-cell {
  padding: 14px 18px;
  font-weight: 600;
  color: var(--text-muted);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  user-select: none;
}

.sortable-header {
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.sortable-header:hover {
  background-color: #f1f5f9;
  color: var(--primary-color);
}

.sortable-header:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: -2px;
}

.sort-icon {
  display: inline-flex;
  align-items: center;
  margin-left: 6px;
  vertical-align: middle;
  color: var(--text-light);
  font-size: 0.8rem;
  transition: color 0.15s ease, transform 0.15s ease;
}

.sort-active {
  color: var(--primary-color);
  background-color: rgba(37, 99, 235, 0.04);
}

.sort-active .sort-icon {
  color: var(--primary-color);
}

.table-row {
  border-bottom: 1px solid var(--border-color);
  transition: background-color 0.12s ease;
}

.table-row:nth-child(even) {
  background-color: var(--stripe-bg);
}

.table-row:hover {
  background-color: var(--row-hover);
}

.table-row:last-child {
  border-bottom: none;
}

.table-cell {
  padding: 14px 18px;
  color: var(--text-main);
  vertical-align: middle;
}

/* 部署タグ */
.department-tag {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  background-color: #f1f5f9;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
}

.dept-dev {
  background-color: #dbeafe;
  color: #1e40af;
  border: 1px solid #bfdbfe;
}

.dept-sales {
  background-color: #ffedd5;
  color: #9a3412;
  border: 1px solid #fed7aa;
}

.dept-hr {
  background-color: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.dept-general {
  background-color: #f3e8ff;
  color: #6b21a8;
  border: 1px solid #e9d5ff;
}

.dept-marketing {
  background-color: #ffe4e6;
  color: #9f1239;
  border: 1px solid #fecdd3;
}

/* 検索結果が空の状態 */
.empty-state {
  padding: 48px 24px;
  text-align: center;
}

.empty-text {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  body {
    padding: 12px 8px;
  }

  .app-container {
    padding: 20px 16px;
    gap: 18px;
  }

  .title {
    font-size: 1.35rem;
  }

  .controls-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .search-box {
    width: 100%;
    min-width: 0;
  }

  .reset-btn {
    justify-content: center;
    width: 100%;
  }

  .stats-badge {
    justify-content: center;
  }

  .table-header-cell,
  .table-cell {
    padding: 12px 10px;
    font-size: 0.88rem;
  }
}

