import React, { useState, useMemo } from 'react';
import { employees } from './data/employees';
import { Employee, SortKey, SortOrder } from './types';

const App: React.FC = () => {
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [sortKey, setSortKey] = useState<SortKey | null>(null);
  const [sortOrder, setSortOrder] = useState<SortOrder>(null);

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      if (sortOrder === 'asc') {
        setSortOrder('desc');
      } else if (sortOrder === 'desc') {
        setSortOrder(null);
        setSortKey(null);
      } else {
        setSortOrder('asc');
      }
    } else {
      setSortKey(key);
      setSortOrder('asc');
    }
  };

  const handleReset = () => {
    setSearchQuery('');
    setSortKey(null);
    setSortOrder(null);
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    let result = employees.filter((employee: Employee) => {
      if (!query) return true;
      const matchName = employee.name.toLowerCase().includes(query);
      const matchEmail = employee.email.toLowerCase().includes(query);
      return matchName || matchEmail;
    });

    if (sortKey && sortOrder) {
      result = [...result].sort((a: Employee, b: Employee) => {
        let valA = a[sortKey];
        let valB = b[sortKey];

        if (typeof valA === 'string' && typeof valB === 'string') {
          const comparison = valA.localeCompare(valB, 'ja');
          return sortOrder === 'asc' ? comparison : -comparison;
        }

        if (typeof valA === 'number' && typeof valB === 'number') {
          return sortOrder === 'asc' ? valA - valB : valB - valA;
        }

        return 0;
      });
    }

    return result;
  }, [searchQuery, sortKey, sortOrder]);

  const getSortIcon = (key: SortKey) => {
    if (sortKey !== key || !sortOrder) {
      return <span className="sort-icon">↕</span>;
    }
    return <span className="sort-icon">{sortOrder === 'asc' ? '▲' : '▼'}</span>;
  };

  const getDepartmentClass = (department: string): string => {
    switch (department) {
      case '開発部':
        return 'dept-dev';
      case '営業部':
        return 'dept-sales';
      case '人事部':
        return 'dept-hr';
      case '総務部':
        return 'dept-general';
      case 'マーケティング部':
        return 'dept-marketing';
      default:
        return '';
    }
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">社員名簿管理システム</h1>
        <p className="subtitle">社員情報の検索、ソート、一覧確認が可能です。</p>
      </header>

      <section className="controls-bar" aria-label="検索・フィルターコントロール">
        <div className="search-box">
          <svg
            className="search-icon"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
            />
          </svg>
          <input
            type="text"
            className="search-input"
            placeholder="氏名またはメールアドレスで検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            aria-label="氏名またはメールアドレスで検索"
          />
        </div>

        <button
          type="button"
          className="reset-btn"
          onClick={handleReset}
          aria-label="検索条件と並べ替えをリセット"
        >
          <svg
            width="16"
            height="16"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
            />
          </svg>
          条件をリセット
        </button>

        <div className="stats-badge">
          表示中: {filteredAndSortedEmployees.length} / {employees.length} 件
        </div>
      </section>

      <div className="table-container">
        <table className="employee-table">
          <thead className="table-head">
            <tr>
              <th className="table-header-cell" style={{ width: '80px' }}>ID</th>
              <th
                className={`table-header-cell sortable-header ${sortKey === 'name' ? 'sort-active' : ''}`}
                onClick={() => handleSort('name')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleSort('name');
                  }
                }}
                tabIndex={0}
                role="button"
                aria-label={`氏名で並べ替え${sortKey === 'name' ? (sortOrder === 'asc' ? '（昇順）' : '（降順）') : ''}`}
              >
                氏名 {getSortIcon('name')}
              </th>
              <th
                className={`table-header-cell sortable-header ${sortKey === 'department' ? 'sort-active' : ''}`}
                onClick={() => handleSort('department')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleSort('department');
                  }
                }}
                tabIndex={0}
                role="button"
                aria-label={`部署で並べ替え${sortKey === 'department' ? (sortOrder === 'asc' ? '（昇順）' : '（降順）') : ''}`}
              >
                部署 {getSortIcon('department')}
              </th>
              <th
                className={`table-header-cell sortable-header ${sortKey === 'age' ? 'sort-active' : ''}`}
                onClick={() => handleSort('age')}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handleSort('age');
                  }
                }}
                tabIndex={0}
                role="button"
                aria-label={`年齢で並べ替え${sortKey === 'age' ? (sortOrder === 'asc' ? '（昇順）' : '（降順）') : ''}`}
              >
                年齢 {getSortIcon('age')}
              </th>
              <th className="table-header-cell">メールアドレス</th>
            </tr>
          </thead>
          <tbody>
            {filteredAndSortedEmployees.length > 0 ? (
              filteredAndSortedEmployees.map((employee: Employee) => (
                <tr key={employee.id} className="table-row">
                  <td className="table-cell">{employee.id}</td>
                  <td className="table-cell" style={{ fontWeight: 500 }}>
                    {employee.name}
                  </td>
                  <td className="table-cell">
                    <span className={`department-tag ${getDepartmentClass(employee.department)}`}>
                      {employee.department}
                    </span>
                  </td>
                  <td className="table-cell">{employee.age} 歳</td>
                  <td className="table-cell">{employee.email}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} className="empty-state">
                  <p className="empty-text">該当する社員が見つかりませんでした。</p>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

